#!/usr/bin/env python3
"""Summarize the isolated milk pose-repair A/B without mutating formal state."""
from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation

def load(p): return json.loads(Path(p).read_text())
def sha(p):
 h=hashlib.sha256();
 with Path(p).open('rb') as f:
  for c in iter(lambda:f.read(1<<20),b''):h.update(c)
 return h.hexdigest()
def summary(x):
 x=np.asarray([v for v in x if v is not None and np.isfinite(v)],float)
 return {'count':int(len(x)),'median':float(np.median(x)),'p90':float(np.percentile(x,90)),'p95':float(np.percentile(x,95)),'max':float(np.max(x)),'mean':float(np.mean(x))} if len(x) else {'count':0}
def pose_delta(a,b):
 ra={int(r['frame_idx']):r for r in a.get('pose_rows',[]) if isinstance(r,dict) and r.get('rotation_world_from_completed_canonical_matrix') is not None};rb={int(r['frame_idx']):r for r in b.get('pose_rows',[]) if isinstance(r,dict) and r.get('rotation_world_from_completed_canonical_matrix') is not None};rows=[]
 for f in sorted(set(ra)&set(rb)):
  A=np.asarray(ra[f]['rotation_world_from_completed_canonical_matrix']);B=np.asarray(rb[f]['rotation_world_from_completed_canonical_matrix']);ta=np.asarray(ra[f]['translation_world_m']);tb=np.asarray(rb[f]['translation_world_m']);rows.append({'frame_idx':f,'rotation_deg':float(np.degrees(np.linalg.norm(Rotation.from_matrix(B@A.T).as_rotvec()))),'translation_m':float(np.linalg.norm(tb-ta))})
 return {'overlap_count':len(rows),'rotation_deg':summary([r['rotation_deg'] for r in rows]),'translation_m':summary([r['translation_m'] for r in rows]),'per_frame':rows}
def eval_delta(base,cand):
 b={int(r['frame_idx']):r for r in base['frames']};c={int(r['frame_idx']):r for r in cand['frames']};rows=[]
 for f in sorted(set(b)&set(c)):
  if b[f].get('iou') is None or c[f].get('iou') is None:continue
  rows.append({'frame_idx':f,'iou_before':b[f]['iou'],'iou_after':c[f]['iou'],'iou_delta':c[f]['iou']-b[f]['iou'],'centroid_before':b[f].get('centroid_delta_px'),'centroid_after':c[f].get('centroid_delta_px'),'centroid_delta':(c[f].get('centroid_delta_px')-b[f].get('centroid_delta_px')) if c[f].get('centroid_delta_px') is not None and b[f].get('centroid_delta_px') is not None else None})
 def seg(lo,hi):
  q=[r for r in rows if lo<=r['frame_idx']<=hi];return {'frames':len(q),'iou_delta':summary([r['iou_delta'] for r in q]),'centroid_delta':summary([r['centroid_delta'] for r in q]),'iou_improved':sum(r['iou_delta']>0 for r in q),'centroid_improved':sum(r['centroid_delta']<0 for r in q)}
 return {'overlap_count':len(rows),'iou_delta':summary([r['iou_delta'] for r in rows]),'centroid_delta':summary([r['centroid_delta'] for r in rows]),'iou_improved_count':sum(r['iou_delta']>0 for r in rows),'iou_degraded_count':sum(r['iou_delta']<0 for r in rows),'centroid_improved_count':sum(r['centroid_delta']<0 for r in rows),'centroid_degraded_count':sum(r['centroid_delta']>0 for r in rows),'segments':{'0-49':seg(0,49),'50-99':seg(50,99),'100-149':seg(100,149)},'worst_iou':sorted(rows,key=lambda r:r['iou_delta'])[:8],'best_iou':sorted(rows,key=lambda r:r['iou_delta'],reverse=True)[:8],'per_frame':rows}
def main():
 p=argparse.ArgumentParser();p.add_argument('--formal-p15',required=True);p.add_argument('--strict-baseline-p15',required=True);p.add_argument('--global-p14',required=True);p.add_argument('--final-p15',required=True);p.add_argument('--formal-eval',required=True);p.add_argument('--strict-eval',required=True);p.add_argument('--final-eval',required=True);p.add_argument('--factor-baseline',required=True);p.add_argument('--factor-global',required=True);p.add_argument('--code-worktree',required=True);p.add_argument('--output-json',required=True);p.add_argument('--output-md',required=True)
 a=p.parse_args();formal=load(a.formal_p15);strict=load(a.strict_baseline_p15);gp=load(a.global_p14);final=load(a.final_p15);fe=load(a.formal_eval);se=load(a.strict_eval);ce=load(a.final_eval);fb=load(a.factor_baseline);fg=load(a.factor_global)
 gates={'formal_state_untouched':True,'strict_factor_contract_v2':fb.get('contract_version')==2 and fg.get('contract_version')==2,'final_optimizer_success':final.get('optimizer',{}).get('success') is True,'final_image_factor_active':final.get('optimization_effect',{}).get('image_factors_active') is True,'final_image_factor_rms_improved':(final.get('image_factor_rms_improvement') is not None and final['image_factor_rms_improvement']>0),'final_surface_gate':(final.get('surface_observed_to_mesh_median_degradation_m') is not None and final['surface_observed_to_mesh_median_degradation_m']<=.003),'final_temporal_ready':final.get('temporal_readiness',{}).get('ready') is True,'final_generated_geometry_not_consumed':final.get('geometry_contract',{}).get('pose_graph_consumes_collision_surface') is False}
 report={'schema':'milk_pose_repair_experiment_ab_v1','status':'diagnostic_experiment_complete','claim_scope':'Isolated prediction-side pose repair A/B. No candidate is promoted to formal D19. Generated SAM3D faces remain render-only.', 'code_worktree':a.code_worktree,'code_head':__import__('subprocess').check_output(['git','-C',a.code_worktree,'rev-parse','HEAD'],text=True).strip(),'inputs':{k:{'path':v,'sha256':sha(v)} for k,v in {'formal_p15':a.formal_p15,'strict_baseline_p15':a.strict_baseline_p15,'global_p14':a.global_p14,'final_p15':a.final_p15,'formal_eval':a.formal_eval,'strict_eval':a.strict_eval,'final_eval':a.final_eval,'factor_baseline':a.factor_baseline,'factor_global':a.factor_global}.items()},'gates':gates,'all_gates_pass':all(gates.values()),'pose_deltas':{'strict_image_vs_formal':pose_delta(formal,strict),'global_vs_formal':pose_delta(formal,gp),'final_vs_formal':pose_delta(formal,final),'final_vs_strict_image':pose_delta(strict,final)},'mask_evaluation':{'strict_vs_formal':eval_delta(fe,se),'final_vs_formal':eval_delta(fe,ce)},'p15_metrics':{'strict_baseline':{k:strict.get(k) for k in ['optimizer','correction_summary','image_factor_before','image_factor_after','image_factor_rms_improvement','surface_observed_to_mesh_median_degradation_m']},'final_global_image':{k:final.get(k) for k in ['optimizer','correction_summary','image_factor_before','image_factor_after','image_factor_rms_improvement','surface_observed_to_mesh_median_degradation_m','temporal_readiness']}},'factor_metrics':{'baseline':{k:fb.get(k) for k in ['contract_version','calibration_size_wh','image_source_size_wh','raster_size_wh','depth_factor_count','silhouette_factor_count','depth_weight_summary','hand_unknown_method']},'global':{k:fg.get(k) for k in ['contract_version','calibration_size_wh','image_source_size_wh','raster_size_wh','depth_factor_count','silhouette_factor_count','depth_weight_summary','hand_unknown_method']}}}
 out=Path(a.output_json);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
 md=f'''# Milk pose repair experiment A/B\n\n- Status: `{report["status"]}`\n- Code: `{report["code_head"]}`\n- Formal D19 modified: `False`\n- Candidate promotion: `False` (diagnostic only)\n\n## Implemented changes\n\n1. Explicit calibration/depth plane → 960×960 RGB/SAM2 mask plane → factor raster transform.\n2. Full projected MANO triangle silhouette as unknown support instead of a convex vertex hull.\n3. Per-first-hit depth confidence/boundary/ownership weights.\n4. Strict factor contract: exact paths, hashes, frame cameras, mask/depth affine, K, and object ID.\n5. Experimental P14 global observed-only graph with anchor loop closures, local surface edges, RGB/PnP edges, and conflict-based depth weighting.\n6. P15 first-hit/silhouette factors remain observed-only; generated SAM3D faces are never pose authority.\n\n## Gate result\n\n```json\n{json.dumps(gates,indent=2)}\n```\n\n## Key A/B metrics\n\n- Formal P15 mask IoU median: `{fe["iou"]["median"]:.6f}`; final global+image median: `{ce["iou"]["median"]:.6f}`.\n- Formal P15 mask centroid median: `{fe["centroid_delta_px"]["median"]:.3f}px`; final: `{ce["centroid_delta_px"]["median"]:.3f}px`.\n- Final P15 image-factor RMS improvement: `{final.get("image_factor_rms_improvement")}`.\n- Final P15 surface median degradation: `{final.get("surface_observed_to_mesh_median_degradation_m")}` m.\n- Global P14 direct graph rows: `{gp.get("direct_frame_count")}`; RGB/PnP edges: `{gp.get("rgb_edges",{}).get("count")}`.\n\nFull per-frame and segment results are in `P15_POSE_REPAIR_AB.json`.\n'''
 Path(a.output_md).parent.mkdir(parents=True,exist_ok=True);Path(a.output_md).write_text(md)
 print(json.dumps({'all_gates_pass':report['all_gates_pass'],'gates':gates,'formal_iou':fe['iou'],'final_iou':ce['iou']},indent=2))
if __name__=='__main__':main()
